theme-files-before-120.script:
# … 24 lines of help in the full program
[CmdletBinding()]
param(
    [ValidateSet('Dark', 'Light')]
    [string] $BaseTheme = 'Dark',

    [string] $Path,

    [ValidateRange(40, 240)]
    [int] $Width = 120,

    [string] $ExportDirectory
)

Import-Module ConsoleMonster -ErrorAction Stop

if (-not $Path) {
    $Path = Join-Path $PSScriptRoot ('team-' + $BaseTheme.ToLowerInvariant() + '.json')
}

if ($ExportDirectory) {
    $null = New-Item -ItemType Directory -Path $ExportDirectory -Force
    foreach ($preset in 'Dark', 'Light', 'HighContrast', 'ColorBlindSafe') {
        Set-ConsoleTheme -Theme $preset
        Export-ConsoleTheme -Path (Join-Path $ExportDirectory ($preset + '.json'))
    }
}

$targets = @(
    [pscustomobject]@{ Target = 'api-east'; Status = 'Pass'; Detail = 'Ready for rollout' }
    [pscustomobject]@{ Target = 'api-west'; Status = 'Fail'; Detail = 'Health probe timed out' }
    [pscustomobject]@{ Target = 'worker-01'; Status = 'Warn'; Detail = 'Restart scheduled' }
)

$themeReport = New-ConsoleRows -Gap 1 -Content {
    New-ConsoleText -Markup '[accent]Build queue[/] [muted]sample data[/]'
    New-ConsolePanel -Title 'Checks' -Content {
        New-ConsoleStatusList -Content {
            [pscustomobject]@{ Label = 'Restore packages'; Status = 'Pass'; Detail = 'complete' }
            [pscustomobject]@{ Label = 'Run smoke checks'; Status = 'Warn'; Detail = '1 retry' }
            [pscustomobject]@{ Label = 'Deploy api-west'; Status = 'Fail'; Detail = 'blocked' }
            [pscustomobject]@{ Label = 'Publish report'; Status = 'Pending'; Detail = 'queued' }
        }
    }
    $targets |
        New-ConsoleTable -Property Target, Status,
            Detail -StatusProperty Status -Title 'Targets' -Expand
    New-ConsolePanel -Title 'Recent log' -Content {
        New-ConsoleLogRegion -Height 3 -Content {
            [pscustomobject]@{ Message = 'Loaded deployment plan'; Level = 'Info'; AtSeconds = 1 }
            [pscustomobject]@{ Message = 'Smoke check needed one retry'; Level = 'Warning'
                AtSeconds = 3 }
            [pscustomobject]@{ Message = 'api-west health probe timed out'; Level = 'Error'
                AtSeconds = 5 }
        }
    }
}

Set-ConsoleTheme -Theme $BaseTheme
New-ConsoleRule -Title ('Before: built-in ' + $BaseTheme) | Show-Console -Width $Width
$themeReport | Show-Console -Width $Width

Set-ConsoleTheme -Path $Path
New-ConsoleRule -Title ('After: team ' + $BaseTheme.ToLowerInvariant()) | Show-Console -Width $Width
$themeReport | Show-Console -Width $Width

theme-files-before-120.csharp:
StatusList checks = new StatusList()
    .Add("Restore packages", StatusKind.Pass, "complete")
    .Add("Run smoke checks", StatusKind.Warn, "1 retry")
    .Add("Deploy api-west", StatusKind.Fail, "blocked")
    .Add("Publish report", StatusKind.Pending, "queued");
Table targets = new Table
{
    Title = "Targets",
    Expand = true
};
targets.AddColumn(new TableColumn("Target") { IsKey = true });
targets.AddColumn(new TableColumn("Status") { Presenter = CellPresenters.StatusWord });
targets.AddColumn(new TableColumn("Detail") { Flexible = true });
targets.AddValues("api-east", "Pass", "Ready for rollout");
targets.AddValues("api-west", "Fail", "Health probe timed out");
targets.AddValues("worker-01", "Warn", "Restart scheduled");
LogRegion log = new LogRegion
{
    PreferredHeight = 3
};
log.Write("Loaded deployment plan", "info", TimeSpan.FromSeconds(1));
log.Write("Smoke check needed one retry", "warn", TimeSpan.FromSeconds(3));
log.Write("api-west health probe timed out", "err", TimeSpan.FromSeconds(5));
Rows report = new Rows(
    new TextBlock("[accent]Build queue[/] [muted]sample data[/]"),
    new Panel(checks, "Checks"),
    targets,
    new Panel(log, "Recent log"))
{
    Gap = 1
};

// Without a file argument, use the terminal's current theme.
if (args.Length == 0)
{
    Terminal.Write(report);
}
else
{
    using (Terminal.Use(new ReportTarget(Terminal.Target, ThemeFile.Load(args[0]).ToTheme())))
    {
        Terminal.Write(report);
    }
}

