    private readonly Lanes _lanes;
    public RunSummary(Lanes lanes) => _lanes = lanes;
    public Size Measure(Constraints constraints,
        RenderContext context) => Content().Measure(constraints, context);
    public void Render(Region region, RenderContext context) => Content().Render(region, context);
    private IWidget Content()
    {
        Table table = new Table()
            .Border(TableBorder.Minimal)
            .Title("[bold]Run summary[/]")
            .AddColumn("Target", c => c.Wrap(false))
            .AddColumn("Status")
            .AddColumn("Passed")
            .AddColumn("Failed")
            .AddColumn("Warnings")
            .AddColumn("Skipped")
            .AddColumn("Duration");
        int passed = 0, failed = 0, warned = 0, skipped = 0;
        foreach (Lane lane in _lanes.Items)
        {
            string duration = lane.Started.HasValue && lane.Finished.HasValue
                ? NumberFormat.Duration(lane.Finished.Value - lane.Started.Value)
                : "-";
            table.AddRow(Markup.Escape(lane.Label), TableCell.ForStatus(lane.Status),
                lane.Passed.ToString(), lane.Failed.ToString(), lane.Warned.ToString(),
                lane.Skipped.ToString(), duration);
            passed += lane.Passed;
            failed += lane.Failed;
            warned += lane.Warned;
            skipped += lane.Skipped;
        }

        table.SetFooter("[bold]Total[/]", string.Empty, passed.ToString(), failed.ToString(),
            warned.ToString(), skipped.ToString(), string.Empty);
        return new Padding(table, 1, 1, 1, 1);
    }
}

